/**
 * Scenes: data files that place compiled components in a world. A scene is
 * JSON (`Scene`); a prefab is a compiled component plus a description of its
 * props (`PrefabDefinition`, generated by the compiler into `prefabs.ts`).
 * `loadScene` builds the objects. Validation against the prefab schema is a
 * build step (`rge-compile --scenes`), not done here.
 */
import type { GameObject } from "./GameObject.ts";
import type { Transform } from "./Transform.ts";
import type { World } from "./World.ts";

/** The transform fields a scene may set: the object's `placement`. */
export type SceneTransform = Partial<Pick<Transform, "x" | "y" | "z" | "rotation" | "scaleX" | "scaleY" | "global">>;

/** A value in a scene: JSON. */
export type SceneValue = null | boolean | number | string | readonly SceneValue[] | { readonly [key: string]: SceneValue };

export interface SceneEntity {
  /** Author-assigned and unique within the scene: stable across edits, for diffing and hot reload. */
  readonly id: string;
  /** The name of an exported component. */
  readonly prefab: string;
  /** Value props. Callbacks cannot come from data. */
  readonly props?: { readonly [name: string]: SceneValue };
  /** Where the parent places this entity: becomes the object's `placement`. */
  readonly transform?: SceneTransform;
  /** Mounted inside this entity, after the prefab's own children (or at its `{children}` slot, if it renders one). */
  readonly children?: readonly SceneEntity[];
}

export interface Scene {
  readonly version: 1;
  readonly entities: readonly SceneEntity[];
}

/** A prop's type, as the compiler understands it (`PropTypeIR`). */
export type PrefabPropType =
  | { readonly kind: "Primitive"; readonly name: "number" | "string" | "boolean" }
  | { readonly kind: "Literals"; readonly values: readonly (string | number)[] }
  | { readonly kind: "Array"; readonly element: PrefabPropType }
  | { readonly kind: "Function" }
  | { readonly kind: "SourceText"; readonly text: string };

export interface PrefabProp {
  readonly name: string;
  readonly type: PrefabPropType;
  /** Has a `?` or a default: a scene may leave it out. */
  readonly optional: boolean;
  /** Data can set it. False for a type the compiler cannot describe as data (it is "code-only"). */
  readonly settable: boolean;
  /** The default, when it is a constant. */
  readonly default?: SceneValue;
}

export interface PrefabDefinition {
  // `any`: each prefab's `create` takes its own props type, and a registry holds them all.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  create(props?: any): GameObject;
  readonly props: readonly PrefabProp[];
}

export type PrefabRegistry = Readonly<Record<string, PrefabDefinition>>;

/**
 * Build the scene's objects and mount them in `world`. Each entity is
 * created from its prefab, placed (`transform` → `placement`, composing under
 * the component's own state-driven transform), and given its children before
 * anything is mounted, so every object mounts once, children first. Returns
 * every object, nested ones included, by scene id.
 */
export function loadScene(world: World, scene: Scene, prefabs: PrefabRegistry): Map<string, GameObject> {
  const byId = new Map<string, GameObject>();
  const build = (entity: SceneEntity): GameObject => {
    const prefab = Object.hasOwn(prefabs, entity.prefab) ? prefabs[entity.prefab] : undefined;
    if (!prefab)
      throw new Error(
        `Scene entity '${entity.id}': unknown prefab '${entity.prefab}' (known: ${Object.keys(prefabs).join(", ") || "none"}).`
      );
    if (byId.has(entity.id)) throw new Error(`Scene entity '${entity.id}': duplicate id.`);
    const object = prefab.create(entity.props ? { ...entity.props } : undefined);
    byId.set(entity.id, object);
    if (entity.transform) Object.assign(object.placement, entity.transform);
    for (const [index, child] of (entity.children ?? []).entries()) {
      const built = build(child);
      // A component that renders `{children}` takes them there; anything else appends after its own children.
      if (object.acceptsPassedChildren) object.attachPassedChild(built, index);
      else object.addChild(built);
    }
    return object;
  };
  const roots = scene.entities.map(build);
  for (const root of roots) world.mount(root);
  return byId;
}
